create schema if not exists private;
create table public.users(id uuid primary key references auth.users(id) on delete cascade, full_name text, avatar_url text, billing_address jsonb, payment_method jsonb);
create table public.products(id text primary key, active boolean default true, name text, description text, image text, metadata jsonb default '{}'::jsonb);
create table public.prices(id text primary key, product_id text references public.products(id) on delete cascade, active boolean default true, currency text, description text, unit_amount bigint, type text, interval text, interval_count integer, trial_period_days integer, metadata jsonb default '{}'::jsonb);
create table public.customers(id uuid primary key references auth.users(id) on delete cascade, stripe_customer_id text unique not null);
create table public.subscriptions(id text primary key, user_id uuid not null references auth.users(id) on delete cascade, status text, metadata jsonb default '{}'::jsonb, price_id text references public.prices(id), quantity integer, cancel_at_period_end boolean default false, created timestamptz default now(), current_period_start timestamptz default now(), current_period_end timestamptz default now(), ended_at timestamptz, cancel_at timestamptz, canceled_at timestamptz, trial_start timestamptz, trial_end timestamptz);
create table public.songs(id bigint generated by default as identity primary key, user_id uuid references auth.users(id) on delete cascade, author text not null check(length(author) between 1 and 100), title text not null check(length(title) between 1 and 150), song_path text not null, image_path text not null, created_at timestamptz default now(), is_demo boolean not null default false, is_seed boolean not null default false);
create table public.liked_songs(user_id uuid not null references auth.users(id) on delete cascade, song_id bigint not null references public.songs(id) on delete cascade, created_at timestamptz default now(), primary key(user_id,song_id));
create index songs_user_created on public.songs(user_id,created_at desc);
create index songs_title on public.songs(lower(title));
create index subscriptions_user_status on public.subscriptions(user_id,status);
create index prices_product on public.prices(product_id);
create index liked_songs_song on public.liked_songs(song_id);

create function private.is_demo() returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from auth.users where id=auth.uid() and raw_app_meta_data->>'demo'='true');$$;
create function private.is_admin() returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from auth.users where id=auth.uid() and raw_app_meta_data->'groups' @> '["admin"]'::jsonb and coalesce(raw_app_meta_data->>'demo','false') <> 'true');$$;
create function private.is_demo_admin() returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from auth.users where id=auth.uid() and raw_app_meta_data->>'demo'='true' and raw_app_meta_data->'groups' @> '["demo_admin"]'::jsonb);$$;
create function private.can_upload() returns boolean language sql stable security definer set search_path='' as $$select auth.uid() is not null and (private.is_admin() or private.is_demo() or exists(select 1 from public.subscriptions where user_id=auth.uid() and status in ('active','trialing') and current_period_end>now()));$$;
create function private.make_profile() returns trigger language plpgsql security definer set search_path='' as $$begin insert into public.users(id,full_name,avatar_url) values(new.id,coalesce(new.raw_user_meta_data->>'full_name',new.raw_user_meta_data->>'name'),new.raw_user_meta_data->>'avatar_url');return new;end;$$;
create trigger on_auth_user_created after insert on auth.users for each row execute function private.make_profile();

create function private.validate_song() returns trigger language plpgsql security definer set search_path='' as $$
begin
 if auth.uid() is not null then
  if tg_op='INSERT' then
   if new.user_id is distinct from auth.uid() or new.is_seed then raise exception 'Invalid song owner'; end if;
   if not private.can_upload() then raise exception 'An active test subscription is required to upload'; end if;
   if (select count(*) from public.songs where user_id=auth.uid())>=20 then raise exception 'Library upload limit reached (20 songs)';end if;
   new.is_demo:=private.is_demo();
  else
   if new.user_id is distinct from old.user_id or new.is_demo is distinct from old.is_demo or new.is_seed is distinct from old.is_seed or new.song_path is distinct from old.song_path or new.image_path is distinct from old.image_path then raise exception 'Song ownership and file paths cannot be changed';end if;
  end if;
  if tg_op='INSERT' and (split_part(new.song_path,'/',1)<>auth.uid()::text or split_part(new.image_path,'/',1)<>auth.uid()::text) then raise exception 'Upload files to your own folder';end if;
 end if;
 return new;
end;$$;
create trigger validate_song before insert or update on public.songs for each row execute function private.validate_song();

alter table public.users enable row level security;
alter table public.products enable row level security;
alter table public.prices enable row level security;
alter table public.customers enable row level security;
alter table public.subscriptions enable row level security;
alter table public.songs enable row level security;
alter table public.liked_songs enable row level security;
grant usage on schema public,private to anon,authenticated;
grant select on public.songs,public.products,public.prices to anon,authenticated;
grant select,insert,update,delete on public.liked_songs,public.songs to authenticated;
grant select,update on public.users to authenticated;
grant select on public.subscriptions to authenticated;
grant usage,select on sequence public.songs_id_seq to authenticated;
create policy no_client_customer_access on public.customers for all to anon,authenticated using(false) with check(false);
create policy own_profile on public.users for select to authenticated using(id=(select auth.uid()));
create policy update_profile on public.users for update to authenticated using(id=(select auth.uid())) with check(id=(select auth.uid()));
create policy public_products on public.products for select to anon,authenticated using(active);
create policy public_prices on public.prices for select to anon,authenticated using(active);
create policy own_subscription on public.subscriptions for select to authenticated using(user_id=(select auth.uid()));
create policy public_songs on public.songs for select to anon,authenticated using(is_seed or not is_demo or user_id=(select auth.uid()) or ((select private.is_demo_admin()) and is_demo) or (select private.is_admin()));
create policy own_song_insert on public.songs for insert to authenticated with check(user_id=(select auth.uid()) and (select private.can_upload()) and not is_seed);
create policy song_update on public.songs for update to authenticated using(user_id=(select auth.uid()) or (select private.is_admin()) or ((select private.is_demo_admin()) and is_demo)) with check(user_id=(select auth.uid()) or (select private.is_admin()) or ((select private.is_demo_admin()) and is_demo));
create policy song_delete on public.songs for delete to authenticated using(user_id=(select auth.uid()) or (select private.is_admin()) or ((select private.is_demo_admin()) and is_demo));
create policy own_likes on public.liked_songs for all to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()) and exists(select 1 from public.songs where id=song_id));

insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values
 ('songs','songs',true,10485760,array['audio/mpeg','audio/mp3','audio/wav','audio/x-wav','audio/ogg']),
 ('images','images',true,2097152,array['image/jpeg','image/png','image/webp']);
create function private.storage_room() returns boolean language sql stable security definer set search_path='' as $$select (select count(*) from storage.objects where bucket_id in ('songs','images') and (storage.foldername(name))[1]=auth.uid()::text)<40;$$;
create policy own_upload on storage.objects for insert to authenticated with check(bucket_id in ('songs','images') and (storage.foldername(name))[1]=(select auth.uid())::text and (select private.can_upload()) and (select private.storage_room()));
create policy own_files_read on storage.objects for select to authenticated using(bucket_id in ('songs','images') and (storage.foldername(name))[1]=(select auth.uid())::text);
create policy own_files_delete on storage.objects for delete to authenticated using(bucket_id in ('songs','images') and (storage.foldername(name))[1]=(select auth.uid())::text);

revoke all on all functions in schema private from public,anon,authenticated;
grant execute on function private.is_demo(),private.is_admin(),private.is_demo_admin(),private.can_upload(),private.storage_room() to authenticated;
-- Anonymous catalog reads must be able to evaluate these predicates too.
grant execute on function private.is_admin(),private.is_demo_admin() to anon;
grant all on all tables in schema public to service_role;
grant all on all sequences in schema public to service_role;
